=isHover?3:Math.max(1,cnt/4);ctx.stroke();const ax=ex-dx/len*10,ay=ey-dy/len*10;const angle=Math.atan2(ey-sy,ex-sx);ctx.beginPath();ctx.moveTo(ex,ey);ctx.lineTo(ex-10*Math.cos(angle-.3),ey-10*Math.sin(angle-.3));ctx.lineTo(ex-10*Math.cos(angle+.3),ey-10*Math.sin(angle+.3));ctx.closePath();ctx.fillStyle=isHover?'#f0883e':edgeColor(cnt);ctx.fill()}for(let i=0;i<6;i++){const v=intervals[i],isSelf=hoverNode===i;const selfLoops=homSet[i][i];if(selfLoops>0){const a=-Math.PI/2+i*Math.PI/3;const lx=v.x+28*Math.cos(a),ly=v.y+28*Math.sin(a);ctx.beginPath();ctx.arc(lx,ly,14,0,Math.PI*2);ctx.strokeStyle=isSelf?'#f0883e':(v.type==='perfect'?'#f9758360':'#79c0ff60');ctx.lineWidth=isSelf?2.5:1.5;ctx.stroke();ctx.fillStyle=isSelf?'#f0883e':'#8b949e';ctx.font='bold 9px system-ui';ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillText(selfLoops,lx,ly)}ctx.beginPath();ctx.arc(v.x,v.y,isSelf?26:22,0,Math.PI*2);ctx.fillStyle=v.type==='perfect'?(isSelf?'#f97583':'#f9758390'):(isSelf?'#79c0ff':'#79c0ff90');ctx.fill();ctx.strokeStyle=isSelf?'#fff':'transparent';ctx.lineWidth=2;ctx.stroke();ctx.fillStyle='#fff';ctx.font='bold 13px system-ui';ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillText(v.semi,v.x,v.y-1);ctx.font='10px system-ui';ctx.fillStyle='#c9d1d9';ctx.fillText(v.name,v.x,v.y+13)}}canvas.addEventListener('mousemove',e=>{const rect=canvas.getBoundingClientRect();const mx=e.clientX-rect.left,my=e.clientY-rect.top;hoverNode=-1;hoverEdge=null;for(let i=0;i<6;i++){const v=intervals[i];if(Math.hypot(mx-v.x,my-v.y)<26){hoverNode=i;const inSum=homSet.reduce((s,row)=>s+row[i],0);const outSum=homSet[i].reduce((s,c)=>s+c,0);info.innerHTML=`<b>${fullNames[v.semi]}</b> (${v.semi} semitones)<br>Type: ${v.type==='perfect'?'<span style=\"color:#f97583\">Perfect</span>':'<span style=\"color:#79c0ff\">Imperfect</span>'}<br>Self-loops: ${homSet[i][i]}<br>Incoming VLs: ${inSum}<br>Outgoing VLs: ${outSum}`;draw();return}}for(let i=0;i<6;i++)for(let j=0;j<6;j++){if(i===j)continue;cons