      "html": "<!DOCTYPE html><html lang='en'><head><meta charset='UTF-8'><meta name='viewport' content='width=device-width,initial-scale=1'><title>Counterpoint Quiver</title><style>*{margin:0;padding:0;box-sizing:border-box}body{background:#0a0a1a;color:#e0e0e0;font-family:'Segoe UI',system-ui,sans-serif;display:flex;flex-direction:column;align-items:center;min-height:100vh;padding:20px}h1{font-size:1.5rem;margin-bottom:4px;color:#88ccff}h2{font-size:.95rem;font-weight:400;color:#889;margin-bottom:16px}.container{display:flex;gap:24px;flex-wrap:wrap;justify-content:center;align-items:flex-start}canvas{border-radius:12px;background:#111;cursor:pointer}#info{width:280px;background:#161625;border-radius:12px;padding:16px;font-size:.85rem;line-height:1.6}.legend{margin-top:12px;display:flex;flex-direction:column;gap:6px}.legend-item{display:flex;align-items:center;gap:8px}.dot{width:14px;height:14px;border-radius:50%}.perfect{background:#ff6b6b}.imperfect{background:#51cf66}.badge{display:inline-block;padding:2px 8px;border-radius:4px;font-size:.75rem;font-weight:600;margin-left:4px}.badge-p{background:#ff6b6b33;color:#ff6b6b}.badge-i{background:#51cf6633;color:#51cf66}</style></head><body><h1>The Counterpoint Quiver</h1><h2>Directed graph of permitted voice leadings in first-species counterpoint</h2><div class='container'><canvas id='c' width='560' height='560'></canvas><div id='info'><strong>Click a node</strong> to see its connections.<div id='details'><p style='margin-top:12px;color:#667'>Nodes = consonant intervals mod 12.<br>Edge width ∝ number of permitted voice leadings.<br><br>Perfect consonances (red) have restricted incoming edges due to the parallel-motion prohibition.</p></div><div class='legend' style='margin-top:16px'><div class='legend-item'><div class='dot perfect'></div><span>Perfect consonance</span></div><div class='legend-item'><div class='dot imperfect'></div><span>Imperfect consonance</span></div></div></div></div><script>const C=document.getElementById('c'),X=C.getContext('2d');const N=12,CONS=[0,3,4,7,8,9],PERF=new Set([0,7]);const NAMES={0:'Unison (P1)',3:'Minor 3rd',4:'Major 3rd',7:'Perfect 5th',8:'Minor 6th',9:'Major 6th'};const W=C.width,H=C.height,CX=W/2,CY=H/2,R=190;const nodes=CONS.map((v,i)=>{const a=-Math.PI/2+i*2*Math.PI/6;return{v,x:CX+R*Math.cos(a),y:CY+R*Math.sin(a),r:28}});function homCount(s,t){let c=0;for(let b=0;b<N;b++){const sp=(t-s+b+N*3)%N;const par=(b%N===sp%N)&&(b%N!==0);if(PERF.has(t%N)&&par)continue;c++}return c}const edges=[];CONS.forEach(s=>CONS.forEach(t=>{const c=homCount(s,t);edges.push({s,t,count:c})}));let selected=null;function nodeAt(mx,my){for(const n of nodes){const dx=mx-n.x,dy=my-n.y;if(dx*dx+dy*dy<=n.r*n.r)return n}return null}function draw(){X.clearRect(0,0,W,H);edges.forEach(e=>{if(e.s===e.t)return;const sn=nodes.find(n=>n.v===e.s),tn=nodes.find(n=>n.v===e.t);const dx=tn.x-sn.x,dy=tn.y-sn.y,d=Math.sqrt(dx*dx+dy*dy);const ux=dx/d,uy=dy/d;const sx=sn.x+sn.r*ux,sy=sn.y+sn.r*uy;const ex=tn.x-tn.r*ux,ey=tn.y-tn.r*uy;const lw=Math.max(1,e.count/4);let alpha=0.18;if(selected!==null){alpha=(e.s===selected.v||e.t===selected.v)?0.7:0.06}X.beginPath();X.moveTo(sx,sy);const cpx=(sx+ex)/2-uy*12,cpy=(sy+ey)/2+ux*12;X.quadraticCurveTo(cpx,cpy,ex,ey);X.strokeStyle=PERF.has(e.t)?`rgba(255,107,107,${alpha})`:`rgba(81,207,102,${alpha})`;X.lineWidth=lw;X.stroke();const ax=ex-cpx,ay=ey-cpy,ad=Math.sqrt(ax*ax+ay*ay);const arx=ax/ad,ary=ay/ad;if(alpha>0.1){X.beginPath();X.moveTo(ex,ey);X.lineTo(ex-8*arx+4*ary,ey-8*ary-4*arx);X.lineTo(ex-8*arx-4*ary,ey-8*ary+4*arx);X.closePath();X.fillStyle=PERF.has(e.t)?`rgba(255,107,107,${alpha})`:`rgba(81,207,102,${alpha})`;X.fill()}});nodes.forEach(n=>{const selfCount=homCount(n.v,n.v);if(selected===null||selected.v===n.v){const sa=-Math.PI/2+CONS.indexOf(n.v)*2*Math.PI/6;X.beginPath();X.arc(n.x+(n.r+12)*Math.cos(sa),n.y+(n.r+12)*Math.sin(sa),14,0,2*Math.PI);X.strokeStyle=PERF.has(n.v)?'rgba(255,107,107,0.5)':'rgba(81,207,102,0.5)';X.lineWidth=Math.max(1,selfCount/3);X.stroke();X.fillStyle='#0a0a1a';X.fill();X.fillStyle='#aaa';X.font='9px sans-serif';X.textAlign='center';X.textBaseline='middle';X.fillText(selfCount,n.x+(n.r+12)*Math.cos(sa),n.y+(n.r+12)*Math.sin(sa))}const glow=selected&&selected.v===n.v;X.beginPath();X.arc(n.x,n.y,n.r,0,2*Math.PI);const col=PERF.has(n.v)?'#ff6b6b':'#51cf66';X.fillStyle=glow?col:(selected?'#222':'#1a1a2e');X.fill();X.strokeStyle=col;X.lineWidth=glow?3:1.5;X.stroke();X.fillStyle=glow?'#000':'#ddd';X.font='bold 13px sans-serif';X.textAlign='center';X.textBaseline='middle';X.fillText(NAMES[n.v],n.x,n.y-6);X.font='11px sans-serif';X.fillStyle=glow?'#333':'#999';X.fillText(`(${n.v})`,n.x,n.y+10)});if(selected){X.fillStyle='#556';X.font='11px sans-serif';X.textAlign='center';X.fillText('Click background to deselect',CX,H-16)}}C.addEventListener('click',e=>{const rect=C.getBoundingClientRect();const mx=(e.clientX-rect.left)*(W/rect.width);const my=(e.clientY-rect.top)*(H/rect.height);const hit=nodeAt(mx,my);selected=hit;draw();const det=document.getElementById('details');if(!hit){det.innerHTML='<p style=\"margin-top:12px;color:#667\">Nodes = consonant intervals mod 12.<br>Edge width ∝ number of permitted voice leadings.<br><br>Perfect consonances (red) have restricted incoming edges due to the parallel-motion prohibition.</p>';return}const v=hit.v;const isPerfect=PERF.has(v);const badge=isPerfect?'<span class=\"badge badge-p\">PERFECT</span>':'<span class=\"badge badge-i\">IMPERFECT</span>';let h=`<h3 style='margin-top:8px'>${NAMES[v]} ${badge}</h3>`;h+=`<p style='margin-top:8px'><strong>Self-loops:</strong> ${homCount(v,v)}</p>`;const inc=CONS.reduce((a,s)=>a+homCount(s,v),0);const out=CONS.reduce((a,t)=>a+homCount(v,t),0);h+=`<p><strong>Total incoming:</strong> ${inc}</p>`;h+=`<p><strong>Total outgoing:</strong> ${out}</p>`;h+='<table style=\"margin-top:10px;width:100%;font-size:.8rem\"><tr><th style=\"text-align:left\">From</th><th>Count</th></tr>';CONS.forEach(s=>{const c=homCount(