X.fillStyle='#3a1a1a';X.strokeStyle='#ff6b6b';X.lineWidth=2.5}else if(origCons&&!isMapped){X.fillStyle='#2a2a1a';X.strokeStyle='#ffd43b88';X.lineWidth=1.5}else{X.fillStyle='#1a1a2a';X.strokeStyle='#333';X.lineWidth=1}}X.fill();X.stroke();X.fillStyle=inActive?'#fff':'#666';X.font=inActive?'bold 11px sans-serif':'10px sans-serif';X.textAlign='center';X.textBaseline='middle';X.fillText(NAMES[i],p.x,p.y-3);X.font='9px sans-serif';X.fillStyle=inActive?'#aaa':'#555';X.fillText(i+'',p.x,p.y+9)}X.fillStyle='#556';X.font='11px sans-serif';X.textAlign='center';const label=mode==='orig'?'Consonant intervals: {0, 3, 4, 7, 8, 9}':'After swap: {0, 3, 4, 5, 8, 9} — note 5 replaces 7!';X.fillText(label,CX,H-12)}const tbody=document.getElementById('tbody');tbody.innerHTML='';[0,3,4,7,8,9].forEach(v=>{const sv=(12-v)%12;const survives=CONS.has(sv);const tr=document.createElement('tr');tr.innerHTML=`<td>${FULL_NAMES[v]||v} (${v})</td><td>${NAMES[sv]} (${sv})</td><td class='${survives?'ok':'bad'}'>${survives?'✓ Consonant':'✗ Dissonant!'}</td>`;tbody.appendChild(tr)});draw()</script></body></html>"
