      "html": "<!DOCTYPE html><html><head><meta charset='utf-8'><title>Counterpoint Quiver</title><style>*{margin:0;padding:0;box-sizing:border-box}body{font-family:'Segoe UI',system-ui,sans-serif;background:#0a0a1a;color:#e0e0e0;display:flex;flex-direction:column;align-items:center;min-height:100vh;padding:20px}.title{font-size:1.5em;font-weight:300;margin-bottom:5px;color:#fff}.subtitle{font-size:.85em;color:#888;margin-bottom:15px}canvas{border-radius:12px;background:#12122a;box-shadow:0 4px 30px rgba(0,0,0,.5);cursor:pointer}.info-panel{margin-top:15px;background:#1a1a35;border-radius:10px;padding:15px 25px;max-width:700px;width:100%;font-size:.9em;line-height:1.6}.legend{display:flex;gap:20px;margin-top:10px;font-size:.8em}.legend-item{display:flex;align-items:center;gap:6px}.dot{width:12px;height:12px;border-radius:50%}.perfect{background:#ff6b6b}.imperfect{background:#4ecdc4}</style></head><body><div class='title'>The Counterpoint Quiver</div><div class='subtitle'>Click an interval to explore its voice-leading connections</div><canvas id='c' width='700' height='500'></canvas><div class='info-panel' id='info'>Click any interval node to see its incoming/outgoing voice leadings and self-loop count.</div><div class='legend'><div class='legend-item'><div class='dot perfect'></div>Perfect consonance (1 self-loop)</div><div class='legend-item'><div class='dot imperfect'></div>Imperfect consonance (12 self-loops)</div></div><script>const canvas=document.getElementById('c'),ctx=canvas.getContext('2d'),info=document.getElementById('info');const W=700,H=500,CX=W/2,CY=H/2-10,R=160;const intervals=[{id:0,name:'Unison',short:'P1',sem:0,perfect:true},{id:1,name:'Minor 3rd',short:'m3',sem:3,perfect:false},{id:2,name:'Major 3rd',short:'M3',sem:4,perfect:false},{id:3,name:'Perfect 5th',short:'P5',sem:7,perfect:true},{id:4,name:'Minor 6th',short:'m6',sem:8,perfect:false},{id:5,name:'Major 6th',short:'M6',sem:9,perfect:false}];const N=12;const edges=[];for(let i=0;i<6;i++){for(let j=0;j<6;j++){let count=0;for(let b=0;b<N;b++){let s=(b+intervals[j].sem-intervals[i].sem+N)%N;let par=b===s&&b!==0;let forbidden=intervals[j].perfect&&par;if(!forbidden)count++}edges.push({from:i,to:j,count:count})}}intervals.forEach((v,i)=>{const a=-Math.PI/2+i*Math.PI*2/6;v.x=CX+R*Math.cos(a);v.y=CY+R*Math.sin(a)});let selected=-1;function draw(){ctx.clearRect(0,0,W,H);edges.forEach(e=>{if(e.from===e.to)return;const s=intervals[e.from],t=intervals[e.to];const highlight=selected===e.from||selected===e.to;ctx.beginPath();const dx=t.x-s.x,dy=t.y-s.y,len=Math.sqrt(dx*dx+dy*dy);const nx=-dy/len*8,ny=dx/len*8;ctx.moveTo(s.x+nx,s.y+ny);ctx.lineTo(t.x+nx,t.y+ny);ctx.strokeStyle=highlight?'rgba(255,200,100,0.6)':'rgba(100,100,200,0.15)';ctx.lineWidth=highlight?2:1;ctx.stroke();if(highlight){const mx=(s.x+nx+t.x+nx)/2+nx*.5,my=(s.y+ny+t.y+ny)/2+ny*.5;ctx.fillStyle='rgba(255,200,100,0.8)';ctx.font='10px sans-serif';ctx.fillText(e.count,mx,my)}const ax=t.x+nx-dx/len*25,ay=t.y+ny-dy/len*25;ctx.beginPath();ctx.moveTo(ax,ay);ctx.lineTo(ax-dx/len*8+ny/len*4,ay-dy/len*8-nx/len*4);ctx.strokeStyle=highlight?'rgba(255,200,100,0.4)':'rgba(100,100,200,0.1)';ctx.lineWidth=1;ctx.stroke()});intervals.forEach((v,i)=>{const isSel=selected===i;const r=isSel?32:26;ctx.beginPath();ctx.arc(v.x,v.y,r,0,Math.PI*2);const grad=ctx.createRadialGradient(v.x-5,v.y-5,2,v.x,v.y,r);if(v.perfect){grad.addColorStop(0,'#ff8a80');grad.addColorStop(1,'#c62828')}else{grad.addColorStop(0,'#80cbc4');grad.addColorStop(1,'#00695c')}ctx.fillStyle=grad;ctx.fill();ctx.strokeStyle=isSel?'#fff':'rgba(255,255,255,0.3)';ctx.lineWidth=isSel?3:1;ctx.stroke();ctx.fillStyle='#fff';ctx.font='bold 13px sans-serif';ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillText(v.short,v.x,v.y-1);ctx.font='10px sans-serif';ctx.fillStyle='rgba(255,255,255,0.6)';ctx.fillText(v.sem+'st',v.x,v.y+12);if(isSel){const loops=v.perfect?1:12;ctx.fillStyle='#ffd54f';ctx.font='bold 11px sans-serif';ctx.fillText(loops+' self-loop'+(loops>1