To(p1.x,p1.y);ctx.lineTo(p2.x,p2.y);ctx.stroke();ctx.setLineDash([]);});}for(let i=0;i<12;i++){const a=-Math.PI/2+i*Math.PI*2/12;const x=cx+R*Math.cos(a),y=cy+R*Math.sin(a);const isCons=CONS.has(i);const isPerf=PERF.has(i);const r=isCons?16:10;ctx.beginPath();ctx.arc(x,y,r,0,Math.PI*2);if(isCons){if(isPerf){ctx.fillStyle='#cc4444';}else{ctx.fillStyle='#339944';}}else{ctx.fillStyle='#333';}ctx.fill();ctx.strokeStyle=i===5?'#ff6b6b':'#555';ctx.lineWidth=i===5?2:1;ctx.stroke();ctx.fillStyle=isCons?'#fff':'#666';ctx.font=(isCons?'bold ':'')+' 11px system-ui';ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillText(SHORT[i],x,y);const lx=cx+(R+30)*Math.cos(a),ly=cy+(R+30)*Math.sin(a);ctx.fillStyle=isCons?'#aaa':'#444';ctx.font='9px system-ui';ctx.fillText(NAMES[i].split('/')[0],lx,ly);}if(animPhase>0){[0,3,4,7,8,9].forEach(i=>{const p=pos(i,animPhase);const neg=(12-i)%12;const ok=CONS.has(neg);ctx.beginPath();ctx.arc(p.x,p.y,8,0,Math.PI*2);ctx.fillStyle=ok?'rgba(81,207,102,0.6)':'rgba(255,107,107,0.8)';ctx.fill();ctx.fillStyle='#fff';ctx.font='bold 9px system-ui';ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillText(SHORT[i],p.x,p.y);});}ctx.fillStyle='#444';ctx.font='11px system-ui';ctx.textAlign='center';ctx.fillText('Green = consonant | Red = perfect | Gray = dissonant',cx,W-10);ctx.fillText('The red ring on 5 (P4) marks the broken mapping σ(7)=5',cx,W-25);}let lastTime=0;function animate(t){if(animating){animPhase=0.5+0.5*Math.sin(t/2000);draw();}requestAnimationFrame(animate);}function toggleAnim(){animating=!animating;const btn=document.getElementById('toggleBtn');btn.textContent=animating?'Pause':'Animate σ';btn.className=animating?'btn active':'btn';if(!animating){animPhase=0;draw();}}draw();requestAnimationFrame(animate);</script></body></html>"
