bel1,x1+barW/2,baseY+20);ctx.fillText(label2,x2+barW/2,baseY+20);ctx.strokeStyle='#333';ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(30,baseY);ctx.lineTo(W-30,baseY);ctx.stroke()}function update(){const sel=document.getElementById('temp').value;const s=systems[sel];const r=compute(s.n,s.cons,s.perf);drawBar('selfloops','Self-Loops at Consonances',r.selfPerf,'Perfect',r.selfImp,'Imperfect','#ff6b6b','#6bcb77');drawBar('incoming','Total Incoming Voice Leadings',r.inPerf,'Perfect',r.inImp,'Imperfect','#ff6b6b','#6bcb77');document.getElementById('s-perf').textContent=r.selfPerf;document.getElementById('s-imp').textContent=r.selfImp;document.getElementById('s-ratio').textContent=r.ratio+':1';document.getElementById('s-in-p').textContent=r.inPerf;document.getElementById('s-in-i').textContent=r.inImp;document.getElementById('s-red').textContent=r.reduction.toFixed(1)+'%'}document.getElementById('temp').addEventListener('change',update);update()</script></body></html>"
