      "html": "<!DOCTYPE html><html><head><meta charset='utf-8'><title>Voice Swap</title><style>*{margin:0;padding:0;box-sizing:border-box}body{font-family:'Segoe UI',system-ui,sans-serif;background:#0d1117;color:#e6edf3;display:flex;flex-direction:column;align-items:center;padding:25px}h1{font-size:1.3em;font-weight:300;margin-bottom:4px}.sub{font-size:.82em;color:#8b949e;margin-bottom:20px}canvas{border-radius:12px;background:#12122a;box-shadow:0 4px 20px rgba(0,0,0,.4)}.explanation{margin-top:15px;max-width:600px;background:#161b22;border-radius:10px;padding:20px;font-size:.88em;line-height:1.7;border:1px solid #30363d}</style></head><body><h1>Voice-Swap Symmetry Breaking</h1><p class='sub'>The involution i → −i (mod 12) fails to preserve consonance</p><canvas id='c' width='600' height='420'></canvas><div class='explanation'><strong>Key insight:</strong> Five of the six consonant intervals survive negation — minor 3rd ↔ major 6th and major 3rd ↔ minor 6th swap perfectly, and the unison maps to itself. But the <span style='color:#ff6b6b'>perfect fifth (7)</span> maps to <span style='color:#ff6b6b'>5 semitones (perfect fourth)</span>, which is <em>dissonant</em> in counterpoint. This single failure formalizes why the bass voice has a privileged role: swapping soprano and bass changes harmonic meaning.</div><script>const c=document.getElementById('c'),ctx=c.getContext('2d');const W=600,H=420,CX=W/2,CY=H/2,R=140;const all=[];for(let i=0;i<12;i++){const a=-Math.PI/2+i*Math.PI*2/12;all.push({sem:i,x:CX+R*Math.cos(a),y:CY+R*Math.sin(a)})}const consonant=new Set([0,3,4,7,8,9]);const names={0:'Unison',1:'m2',2:'M2',3:'m3',4:'M3',5:'P4',6:'Tritone',7:'P5',8:'m6',9:'M6',10:'m7',11:'M7'};let hover=-1;function draw(){ctx.clearRect(0,0,W,H);const pairs=[[0,0],[3,9],[4,8],[7,5],[8,4],[9,3]];pairs.forEach(([a,b])=>{if(a===b)return;const sa=all[a],sb=all[b];ctx.beginPath();ctx.setLineDash([4,4]);const isBroken=!consonant.has(b);ctx.strokeStyle=isBroken?'rgba(255,80,80,0.5)':'rgba(100,220,180,0.3)';ctx.lineWidth=isBroken?2.5:1.5;const cpx=CX+(sa.x+sb.x-2*CX)*0.3,cpy=CY+(sa.y+sb.y-2*CY)*0.3;ctx.moveTo(sa.x,sa.y);ctx.quadraticCurveTo(cpx,cpy,sb.x,sb.y);ctx.stroke();ctx.setLineDash([]);const mx=(sa.x+sb.x)/2+(cpx-CX)*0.15,my=(sa.y+sb.y)/2+(cpy-CY)*0.15;ctx.fillStyle=isBroken?'#ff6b6b':'#4ecdc4';ctx.font='bold 10px sans-serif';ctx.textAlign='center';ctx.fillText(isBroken?'✗ BREAKS':'✓',mx,my)});all.forEach((v,i)=>{const isCons=consonant.has(i);const r=isCons?20:12;ctx.beginPath();ctx.arc(v.x,v.y,r,0,Math.PI*2);if(isCons){const neg=(12-i)%12;const negCons=consonant.has(neg);if(!negCons&&consonant.has(i)){ctx.fillStyle='#c0392b'}else{ctx.fillStyle='#1a6b5a'}}else{ctx.fillStyle=i===5?'#4a1a1a':'#1e2433'}ctx.fill();ctx.strokeStyle=isCons?'rgba(255,255,255,0.6)':'rgba(255,255,255,0.15)';ctx.lineWidth=isCons?2:1;ctx.stroke();ctx.fillStyle=isCons?'#fff':'rgba(255,255,255,0.35)';ctx.font=(isCons?'bold ':'')+' 11px sans-serif';ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillText(names[i],v.x,v.y);if(isCons||i===5){ctx.fillStyle=isCons?'rgba(255,255,255,0.5)':'rgba(255,100,100,0.7)';ctx.font='9px sans-serif';ctx.fillText(i+'st',v.x,v.y+r+12);if(i===5){ctx.fillStyle='#ff6b6b';ctx.font='bold 9px sans-serif';ctx.fillText('DISSONANT',v.x,v.y+r+24)}}});ctx.fillStyle='rgba(255,255,255,0.4)';ctx.font='11px sans-serif';ctx.textAlign='center';ctx.fillText('The chromatic circle (ZMod 12) — consonant intervals highlighted',CX,H-12);ctx.fillText('Arrows show the negation map i → −i',CX,H-28)}draw()</script></body></html>"
