 6th)',9:'M6 (Major 6th)'};const SHORT={0:'P1',3:'m3',4:'M3',7:'P5',8:'m6',9:'M6'};function countArrows(src,tgt){let c=0;for(let b=0;b<12;b++){for(let s=0;s<12;s++){let target=(src+s-b+120)%12;if(target!==tgt)continue;let parallel=(b===s)&&(b!==0);if(PERFECT.has(tgt)&&parallel)continue;c++}}return c}const MATRIX={};CONSONANT.forEach(s=>{CONSONANT.forEach(t=>{MATRIX[s+','+t]=countArrows(s,t)})});const canvas=document.getElementById('quiverCanvas');const ctx=canvas.getContext('2d');const CX=240,CY=240,R=160;const nodePositions={};CONSONANT.forEach((v,i)=>{const angle=-Math.PI/2+i*2*Math.PI/6;nodePositions[v]={x:CX+R*Math.cos(angle),y:CY+R*Math.sin(angle)}});let selectedNode=null;function draw(){ctx.clearRect(0,0,480,480);CONSONANT.forEach(src=>{CONSONANT.forEach(tgt=>{if(src===tgt)return;const count=MATRIX[src+','+tgt];const p1=nodePositions[src],p2=nodePositions[tgt];const dx=p2.x-p1.x,dy=p2.y-p1.y;const len=Math.sqrt(dx*dx+dy*dy);const nx=dx/len,ny=dy/len;const offset=4;const sx=p1.x+ny*offset,sy=p1.y-nx*offset;const ex=p2.x+ny*offset,ey=p2.y-nx*offset;const isHighlighted=selectedNode!==null&&(src===selectedNode||tgt===selectedNode);ctx.beginPath();ctx.moveTo(sx,sy);ctx.lineTo(ex,ey);ctx.strokeStyle=isHighlighted?'rgba(255,183,77,0.7)':'rgba(100,181,246,0.15)';ctx.lineWidth=isHighlighted?Math.max(1,count/4):1;ctx.stroke();if(isHighlighted){const arrowLen=10;const mx=(sx+ex)/2,my=(sy+ey)/2;const ax=mx-arrowLen*nx+arrowLen*ny*0.4;const ay=my-arrowLen*ny-arrowLen*nx*0.4;const bx=mx-arrowLen*nx-arrowLen*ny*0.4;const by=my-arrowLen*ny+arrowLen*nx*0.4;ctx.beginPath();ctx.moveTo(mx,my);ctx.lineTo(ax,ay);ctx.moveTo(mx,my);ctx.lineTo(bx,by);ctx.strokeStyle='rgba(255,183,77,0.5)';ctx.lineWidth=1.5;ctx.stroke()}})});CONSONANT.forEach(v=>{const p=nodePositions[v];const isPerfect=PERFECT.has(v);const isSelected=v===selectedNode;const selfLoops=MATRIX[v+','+v];const radius=isSelected?28:isPerfect?22:20;if(selfLoops>1){ctx.beginPath();ctx.arc(p.x,p.y-radius-8,8,0,2*Math.PI);ctx.strokeStyle='rgba(100,181,246,0.4)';ctx.lineWidth=1;ctx.stroke()}ctx.beginPath();ctx.arc(p.x,p.y,radius,0,2*Math.PI);if(isPerfect){ctx.fillStyle=isSelected?'#e040fb':'#ce93d8';ctx.strokeStyle='#e040fb'}else{ctx.fillStyle=isSelected?'#42a5f5':'#1e88e5';ctx.strokeStyle='#42a5f5'}ctx.lineWidth=isSelected?3:2;ctx.fill();ctx.stroke();ctx.fillStyle='#fff';ctx.font=isSelected?'bold 13px sans-serif':'bold 11px sans-serif';ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillText(SHORT[v],p.x,p.y);ctx.fillStyle='#aaa';ctx.font='10px sans-serif';ctx.fillText(selfLoops+' loop'+(selfLoops!==1?'s':''),p.x,p.y+radius+14)})}canvas.addEventListener('click',e=>{const rect=canvas.getBoundingClientRect();const mx=e.clientX-rect.left,my=e.clientY-rect.top;let clicked=null;CONSONANT.forEach(v=>{const p=nodePositions[v];const d=Math.sqrt((mx-p.x)**2+(my-p.y)**2);if(d<25)clicked=v});selectedNode=clicked===selectedNode?null:clicked;draw();updateInfo()});function updateInfo(){const el=document.getElementById('selectedInfo');if(selectedNode===null){el.innerHTML='Click a node to see its voice-leading connections.';unhighlightMatrix();return}const v=selectedNode;const isPerfect=PERFECT.has(v);let html='<strong>'+NAMES[v]+'</strong><br>';html+='Type: '+(isPerfect?'<span style=\"color:#ce93d8\">Perfect</span>':'<span style=\"color:#64b5f6\">Imperfect</span>')+'<br>';const selfLoops=MATRIX[v+','+v];html+='Self-loops: <strong>'+selfLoops+'</strong><br>';let incoming=0,outgoing=0;CONSONANT.forEach(s=>{incoming+=MATRIX[s+','+v];outgoing+=MATRIX[v+','+s]});html+='Incoming VLs: <strong>'+incoming+'</strong><br>';html+='Outgoing VLs: <strong>'+outgoing+'</strong><br><br>';html+='<span style=\"font-size:.78rem;color:#aaa\">Arrows from this node:</span><br>';CONSONANT.forEach(t=>{const c=MATRIX[v+','+t];html+='<span style=\"font-size:.78rem\">→ '+SHORT[t]+': '+c+' voice leadings</span><br>'});el.innerHTML=html;highlightMatrix(v)}function highlightMatrix(v){document.querySelectorAll('#matrixTable td, #m