x}</style></head><body><div class=\"title\">L¹-Lattice Identity Explorer</div><div class=\"subtitle\">The conservation law: cost(m₁ ⊓ m₂) + cost(m₁ ⊔ m₂) = cost(m₁) + cost(m₂)</div><div class=\"container\"><div class=\"panel\"><h3>Voice Motions</h3><div id=\"voices\">4 voices — enter integer semitone displacements</div><div class=\"row\"><label>m₁</label><input type=\"number\" id=\"m1_0\" value=\"2\"><input type=\"number\" id=\"m1_1\" value=\"-1\"><input type=\"number\" id=\"m1_2\" value=\"3\"><input type=\"number\" id=\"m1_3\" value=\"0\"></div><div class=\"row\"><label>m₂</label><input type=\"number\" id=\"m2_0\" value=\"1\"><input type=\"number\" id=\"m2_1\" value=\"2\"><input type=\"number\" id=\"m2_2\" value=\"-1\"><input type=\"number\" id=\"m2_3\" value=\"4\"></div><button class=\"btn\" onclick=\"compute()\">Compute</button><button class=\"btn\" style=\"background:#7b1fa2;margin-left:8px\" onclick=\"randomize()\">Random</button></div><div class=\"panel\"><h3>Results</h3><div id=\"resultArea\" class=\"result\">Click Compute to see the identity in action.</div><div class=\"bar-container\" id=\"barChart\"></div></div><div class=\"panel\" style=\"font-size:.82rem;color:#aaa;line-height:1.6\"><h3>About This Identity</h3><p><strong>Theorem <code>cost_meet_join_eq</code></strong>: For any voice motions m₁, m₂ in Fin n → ℤ, the L¹ cost of the componentwise minimum (lattice meet ⊓) plus the cost of the componentwise maximum (lattice join ⊔) equals the sum of the individual costs.</p><p style=\"margin-top:8px\">This identity reduces pointwise to |min(a,b)| + |max(a,b)| = |a| + |b| and represents a <em>conservation law</em>: decomposing voice motions via lattice operations redistributes cost without creating or destroying it.</p></div></div><script>function getMotion(prefix){return[0,1,2,3].map(i=>parseInt(document.getElementById(prefix+'_'+i).value)||0)}function cost(m){return m.reduce((s,x)=>s+Math.abs(x),0)}function meet(a,b){return a.map((v,i)=>Math.min(v,b[i]))}function join(a,b){return a.map((v,i)=>Math.max(v,b[i]))}function compute(){const m1=getMotion('m1'),m2=getMotion('m2');const mt=meet(m1,m2),jn=join(m1,m2);const c1=cost(m1),c2=cost(m2),cmt=cost(mt),cjn=cost(jn);const lhs=cmt+cjn,rhs=c1+c2;const ok=lhs===rhs;let html='';html+='m₁ = ['+m1.join(', ')+']    cost(m₁) = '+c1+'\\n';html+='m₂ = ['+m2.join(', ')+']    cost(m₂) = '+c2+'\\n\\n';html+='m₁ ⊓ m₂ = ['+mt.join(', ')+']  cost = '+cmt+'\\n';html+='m₁ ⊔ m₂ = ['+jn.join(', ')+']  cost = '+cjn+'\\n\\n';html+='<span class=\"eq\">'+cmt+' + '+cjn+' = '+lhs+'   vs   '+c1+' + '+c2+' = '+rhs+'</span>\\n';html+='<span class=\"check\">'+(ok?'✅ Identity verified!':'❌ Error — this should never happen')+'</span>\\n\\n';html+='Triangle inequality: cost(m₁+m₂) = '+cost(m1.map((v,i)=>v+m2[i]))+' ≤ '+c1+'+'+c2+' = '+(c1+c2)+'  '+(cost(m1.map((v,i)=>v+m2[i]))<=c1+c2?'✅':'❌');document.getElementById('resultArea').innerHTML=html;const maxVal=Math.max(c1,c2,cmt,cjn,1);const bars=[{label:'cost(m₁)',val:c1,color:'#1e88e5'},{label:'cost(m₂)',val:c2,color:'#42a5f5'},{label:'cost(m₁⊓m₂)',val:cmt,color:'#7b1fa2'},{label:'cost(m₁⊔m₂)',val:cjn,color:'#ce93d8'}];const chart=document.getElementById('barChart');chart.innerHTML='';bars.forEach(b=>{const h=Math.max(4,b.val/maxVal*60);const div=document.createElement('div');div.className='bar';div.style.height=h+'px';div.style.background=b.color;div.style.flex='1';div.innerHTML=b.val+'<div class=\"bar-label\">'+b.label+'</div>';chart.appendChild(div)})}function randomize(){[0,1,2,3].forEach(i=>{document.getElementById('m1_'+i).value=Math.floor(Math.random()*11)-5;document.getElementById('m2_'+i).value=Math.floor(Math.random()*11)-5});compute()}compute()</script></body></html>"
