x.fillStyle='#666';ctx.font='11px monospace';ctx.textAlign='right';ctx.fillText('10^'+val.toFixed(0),pad.l-5,y+4)}ctx.stroke();ctx.strokeStyle='#f59e0b';ctx.lineWidth=2.5;ctx.beginPath();for(let d=1;d<=L;d++){const x=pad.l+(d-1)/(L-1)*cw;const logB=(L-d+1)*Math.log10(A);const y=pad.t+ch*(1-logB/logLib);if(d===1)ctx.moveTo(x,y);else ctx.lineTo(x,y)}ctx.stroke();ctx.strokeStyle='rgba(239,68,68,0.5)';ctx.setLineDash([5,5]);ctx.beginPath();const yCur=pad.t;ctx.moveTo(pad.l,yCur);ctx.lineTo(pad.l+cw,yCur);ctx.stroke();ctx.setLineDash([]);ctx.fillStyle='#888';ctx.font='12px sans-serif';ctx.textAlign='center';ctx.fillText('Minimum Distance d →',pad.l+cw/2,h-5);ctx.save();ctx.translate(12,pad.t+ch/2);ctx.rotate(-Math.PI/2);ctx.fillText('log₁₀(Bound)',0,0);ctx.restore();ctx.fillStyle='#f59e0b';ctx.font='bold 13px sans-serif';ctx.fillText('Singleton Bound: A^(L-d+1)',pad.l+cw/2,pad.t-10)}['A','L','d'].forEach(id=>$(id).addEventListener('input',update));update()</script></body></html>"
