gth===0||m2.length===0){document.getElementById('results').innerHTML='<div style=\"grid-column:1/-1;color:#888;font-size:12px\">Enter valid integer vectors.</div>';return}const meet=vecOp(m1,m2,Math.min);const join=vecOp(m1,m2,Math.max);const sum=vecOp(m1,m2,(a,b)=>a+b);const c1=cost(m1),c2=cost(m2),cMeet=cost(meet),cJoin=cost(join),cSum=cost(sum);const lhs=cMeet+cJoin,rhs=c1+c2;const conserved=lhs===rhs;const triangle=cSum<=c1+c2;const r=document.getElementById('results');r.innerHTML=`<div class='result-box'><div class='val'>${c1}</div><div class='lbl'>cost(m₁)</div></div><div class='result-box'><div class='val'>${c2}</div><div class='lbl'>cost(m₂)</div></div><div class='result-box'><div class='val'>${cSum}</div><div class='lbl'>cost(m₁+m₂) ${triangle?'≤':'>'} ${c1+c2}</div></div><div class='result-box'><div class='val'>${cMeet}</div><div class='lbl'>cost(m₁⊓m₂) = cost(${meet.join(',')})</div></div><div class='result-box'><div class='val'>${cJoin}</div><div class='lbl'>cost(m₁⊔m₂) = cost(${join.join(',')})</div></div><div class='result-box ${conserved?'eq-box':'neq-box'}'><div class='val'>${lhs} = ${rhs} ${conserved?'✓':'✗'}</div><div class='lbl'>Lattice Conservation</div></div>`}calcCost()</script></body></html>"
