n></label><input type=\"range\" id=\"bSlider\" min=\"2\" max=\"4\" value=\"2\"></div></div><div class=\"info\" id=\"countBox\"></div></div><div class=\"card\"><h3 style=\"color:#7eb8ff;margin-bottom:8px\">Attempted Encoding Table</h3><p style=\"font-size:.8em;color:#888;margin-bottom:10px\">Each row is a volume. Each column shows what evaluation function that volume would encode. The <span style=\"color:#ff6666\">red diagonal</span> shows where self-reference breaks — we flip each diagonal entry to construct a function that NO volume encodes.</p><div style=\"overflow-x:auto\"><table id=\"diagTable\"></table></div></div><div class=\"card\"><canvas id=\"vizCanvas\" height=\"300\"></canvas><div class=\"info\" id=\"explainBox\"></div></div></div><script>const aS=document.getElementById('aSlider'),lS=document.getElementById('lSlider'),bS=document.getElementById('bSlider'),aV=document.getElementById('aVal'),lV=document.getElementById('lVal'),bV=document.getElementById('bVal'),countBox=document.getElementById('countBox'),diagTable=document.getElementById('diagTable'),vizCanvas=document.getElementById('vizCanvas'),vizCtx=vizCanvas.getContext('2d'),explainBox=document.getElementById('explainBox');function update(){const A=+aS.value,L=+lS.value,B=+bS.value;aV.textContent=A;lV.textContent=L;bV.textContent=B;const nVols=Math.pow(A,L);const nEvals=Math.pow(B,nVols);countBox.innerHTML=`<b>Volumes:</b> A<sup>L</sup> = ${A}<sup>${L}</sup> = <span class=\"highlight\">${nVols}</span><br><b>Evaluation functions:</b> B<sup>A<sup>L</sup></sup> = ${B}<sup>${nVols}</sup> = <span class=\"highlight\">${nEvals}</span><br><b>Ratio:</b> ${(nEvals/nVols).toFixed(1)}× more functions than volumes — <span style=\"color:#ff6666\">encoding is impossible!</span>`;const vols=[];function genVols(prefix){if(prefix.length===L){vols.push([...prefix]);return}for(let a=0;a<A;a++){prefix.push(a);genVols(prefix);prefix.pop()}}genVols([]);const maxShow=Math.min(nVols,16);const maxEvalShow=Math.min(nEvals,16);const evals=[];function genEvals(prefix){if(evals.length>=maxEvalShow)return;if(prefix.length===nVols){evals.push([...prefix]);return}for(let b=0;b<B;b++){prefix.push(b);genEvals(prefix);prefix.pop()}}genEvals([]);let html='<thead><tr><th>Vol \\\\ Eval#</th>';for(let j=0;j<Math.min(maxShow,maxEvalShow);j++)html+=`<th>f<sub>${j}</sub></th>`;html+='<th>diag′</th></tr></thead><tbody>';const diagNew=[];for(let i=0;i<Math.min(maxShow,maxEvalShow);i++){html+=`<tr><td style=\"color:#7eb8ff\">${vols[i].join('')}</td>`;for(let j=0;j<Math.min(maxShow,maxEvalShow);j++){const val=j<evals.length&&i<evals[j].length?evals[j][i]:'?';const isDiag=i===j;html+=`<td class=\"${isDiag?'diag':''}\">${val}</td>`}const diagVal=i<evals.length&&i<evals[i].length?(evals[i][i]+1)%B:'?';diagNew.push(diagVal);html+=`<td style=\"color:#ffcc00;font-weight:bold\">${diagVal}</td></tr>`}html+='</tbody>';diagTable.innerHTML=html;const W=vizCanvas.width=vizCanvas.offsetWidth*2,H=vizCanvas.height=600;vizCtx.clearRect(0,0,W,H);vizCtx.fillStyle='#1a1a3a';vizCtx.fillRect(0,0,W,H);const cx=W/2,cy=H/2;const rVols=Math.min(W,H)*.35;const rEvals=Math.min(W,H)*.2;vizCtx.strokeStyle='#3a3a5a';vizCtx.lineWidth=2;vizCtx.beginPath();vizCtx.arc(cx-W*.18,cy,rVols,0,Math.PI*2);vizCtx.stroke();vizCtx.fillStyle='#7eb8ff';vizCtx.font='bold 24px sans-serif';vizCtx.textAlign='center';vizCtx.fillText(`Volumes (${nVols})`,cx-W*.18,cy-rVols-15);vizCtx.strokeStyle='#5a3a3a';vizCtx.beginPath();vizCtx.arc(cx+W*.18,cy,rEvals*1.5,0,Math.PI*2);vizCtx.stroke();vizCtx.fillStyle='#ff8888';vizCtx.fillText(`Eval Functions (${nEvals>999?'10^'+Math.log10(nEvals).toFixed(1):nEvals})`,cx+W*.18,cy-rEvals*1.5-15);for(let i=0;i<Math.min(maxShow,8);i++){const ang=Math.PI*2*i/Math.min(maxShow,8)-Math.PI/2;const vx=cx-W*.18+rVols*.7*Math.cos(ang);const vy=cy+rVols*.7*Math.sin(ang);vizCtx.beginPath();vizCtx.arc(vx,vy,14,0,Math.PI*2);vizCtx.fillStyle='#7eb8ff';vizCtx.fill();vizCtx.fillStyle='#000';vizCtx.font='bold 16px monospace';vizCtx.fillText(vols[i].join(''),vx,vy+5)}const showArrows=Math.min(maxShow,8,maxEvalShow);for(let i=0;i<showArrows;i++){const ang1=Math.PI*2*i/showArrows-Math.PI/2;const ang2=Math.PI*2*i/Math.min(maxEvalShow,12)-Math.PI/2;const x1=cx-W*.18+rVols*.7*Math.cos(ang1)+18;const y1=cy+rVols*.7*Math.sin(ang1);const x2=cx+W*.18+rEvals*Math.cos(ang2)-14;const y2=cy+rEvals*Math.sin(ang2);vizCtx.beginPath();vizCtx.moveTo(x1,y1);vizCtx.lineTo(x2,y2);vizCtx.strokeStyle='rgba(255,100,100,0.3)';vizCtx.lineWidth=1.5;vizCtx.stroke()}vizCtx.fillStyle='#ff6666';vizCtx.font='bold 28px sans-serif';vizCtx.fillText('✗',cx,cy+rVols+40);vizCtx.fillStyle='#ff6666';vizCtx.font='20px sans-serif';vizCtx.fillText('No surjection possible!',cx,cy+rVols+70);explainBox.innerHTML=`<b>The Diagonal Argument:</b> Suppose we could encode every evaluation function as a volume. Look at the diagonal of the encoding table: volume <i>i</i> encodes function <i>f<sub>i</sub></i>, and <i>f<sub>i</sub>(vol<sub>i</sub>)</i> is the diagonal entry. Now construct a <span class=\"highlight\">new function</span> that differs from <i>f<sub>i</sub></i> at volume <i>i</i> (by adding 1 mod B). This new function <b>cannot equal any <i>f<sub>i</sub></i></b>, so it has no encoding — contradiction!<br><br>This is the <b>No Universal Self-Evaluator Theorem</b>: the Library cannot faithfully catalog itself.`}aS.oninput=update;lS.oninput=update;bS.oninput=update;update()</script></body></html>"
