te...</div></div><div class='coverage'><h3>Volume Coverage</h3><div class='cov-grid' id='covGrid'></div></div></main><script>const syms='0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ';let seq=[],A=4,L=3;function deBruijn(a,l){if(l===1){const s=[];for(let i=0;i<a;i++)s.push(i);return s}const k=a,n=l;const alphabet=Array.from({length:k},(_,i)=>i);const a_arr=new Array(k*n).fill(0);const sequence=[];function db(t,p){if(t>n){if(n%p===0)for(let j=1;j<=p;j++)sequence.push(a_arr[j])}else{a_arr[t]=a_arr[t-p];db(t+1,p);for(let j=a_arr[t-p]+1;j<k;j++){a_arr[t]=j;db(t+1,t)}}}db(1,1);return sequence}function build(){A=parseInt(document.getElementById('alphaSelect').value);L=parseInt(document.getElementById('lenSelect').value);if(Math.pow(A,L)>100000){alert('Too large to visualize (A^L > 100,000). Try smaller parameters.');return}seq=deBruijn(A,L);const total=Math.pow(A,L);document.getElementById('seqLen').textContent=seq.length.toLocaleString();document.getElementById('totalVols').textContent=total.toLocaleString();const ps=document.getElementById('posSlider');ps.max=seq.length-1;ps.value=0;updateDisplay();const seen=new Set();for(let i=0;i<seq.length;i++){const w=[];for(let j=0;j<L;j++)w.push(seq[(i+j)%seq.length]);seen.add(w.join(','))}document.getElementById('covPct').textContent=((seen.size/total)*100).toFixed(0)+'%';const grid=document.getElementById('covGrid');let gh='';const allVols=[];function gen(prefix){if(prefix.length===L){allVols.push([...prefix]);return}for(let c=0;c<A;c++){prefix.push(c);gen(prefix);prefix.pop()}}gen([]);allVols.forEach(v=>{const key=v.join(',');const found=seen.has(key);const label=v.map(c=>syms[c]).join('');gh+=`<div class='cov-item${found?\" found\":\"\"}'>${label}</div>`});grid.innerHTML=gh}function updateDisplay(){const pos=parseInt(document.getElementById('posSlider').value);document.getElementById('posLabel').textContent='Position: '+pos;let html='';for(let i=0;i<seq.length;i++){const c=syms[seq[i]];const inWindow=((i-pos+seq.length)%seq.length)<L;