y=2*(1-at)*(my-p1.y)+2*at*(p2.y-my);const al=Math.sqrt(adx*adx+ady*ady);const udx=adx/al,udy=ady/al;const sz=8;ctx.fillStyle=color.replace(alpha+'',Math.min(1,alpha*2)+'');ctx.beginPath();ctx.moveTo(ax+udx*sz,ay+udy*sz);ctx.lineTo(ax-udx*sz*0.3+udy*sz*0.5,ay-udy*sz*0.3-udx*sz*0.5);ctx.lineTo(ax-udx*sz*0.3-udy*sz*0.5,ay-udy*sz*0.3+udx*sz*0.5);ctx.fill();}});});CONS.forEach(v=>{const p=positions[v];const isPerfect=PERF.has(v);const isSelected=v===selected;const r=isSelected?28:22;const selfLoops=HOM[v+','+v];if(isSelected){ctx.beginPath();ctx.arc(p.x,p.y,r+6,0,Math.PI*2);ctx.fillStyle='rgba(160,196,255,0.15)';ctx.fill();}ctx.beginPath();ctx.arc(p.x,p.y,r,0,Math.PI*2);const grad=ctx.createRadialGradient(p.x-5,p.y-5,0,p.x,p.y,r);if(isPerfect){grad.addColorStop(0,'#ff9a9a');grad.addColorStop(1,'#cc4444');}else{grad.addColorStop(0,'#7ddf8a');grad.addColorStop(1,'#339944');}ctx.fillStyle=grad;ctx.fill();ctx.strokeStyle=isSelected?'#a0c4ff':'#333';ctx.lineWidth=isSelected?3:1;ctx.stroke();ctx.fillStyle='#fff';ctx.font=`${isSelected?'bold ':' '}14px system-ui`;ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillText(NAMES[v],p.x,p.y-2);ctx.font='10px system-ui';ctx.fillStyle='rgba(255,255,255,0.6)';ctx.fillText(v+' st',p.x,p.y+12);if(isSelected){ctx.font='11px system-ui';ctx.fillStyle='#a0c4ff';ctx.fillText('loops: '+selfLoops,p.x,p.y+r+16);}});ctx.fillStyle='#444';ctx.font='11px system-ui';ctx.textAlign='left';ctx.fillText('Total edges: 410 | Perfect: 61 incoming | Imperfect: 72 incoming',10,510);}function updatePanel(){const panel=document.getElementById('panel-stats');const title=document.getElementById('panel-title');const table=document.getElementById('hom-table');if(selected===null){title.textContent='Click a vertex to explore';panel.innerHTML='';table.innerHTML='';draw();return;}const v=selected;const isPerfect=PERF.has(v);title.textContent=FULL_NAMES[v]+' ('+v+' semitones)';const incoming=CONS.reduce((s,src)=>s+HOM[src+','+v],0);const outgoing=CONS.reduce((s,tgt