th>Swap</th><th>Status</th></tr></thead><tbody id='tbody'></tbody></table><p style='margin-top:12px;color:#ff6b6b'><strong>Key:</strong> The perfect fifth (7) maps to the perfect fourth (5), which is <em>dissonant</em>. The bass voice is structurally privileged.</p></div></div><script>const C=document.getElementById('c'),X=C.getContext('2d');const W=C.width,H=C.height,CX=W/2,CY=H/2,R=160;const CONS=new Set([0,3,4,7,8,9]);const NAMES=['P1','m2','M2','m3','M3','P4','TT','P5','m6','M6','m7','M7'];const FULL_NAMES={0:'Unison',3:'Minor 3rd',4:'Major 3rd',5:'Perfect 4th',7:'Perfect 5th',8:'Minor 6th',9:'Major 6th'};let mode='orig';function showMode(m){mode=m;document.getElementById('btnOrig').className=m==='orig'?'active':'';document.getElementById('btnSwap').className=m==='swap'?'active':'';draw()}function posOf(i){const a=-Math.PI/2+i*2*Math.PI/12;return{x:CX+R*Math.cos(a),y:CY+R*Math.sin(a)}}function draw(){X.clearRect(0,0,W,H);X.strokeStyle='#222';X.lineWidth=1;X.beginPath();X.arc(CX,CY,R,0,2*Math.PI);X.stroke();const activeSet=new Set();if(mode==='orig'){CONS.forEach(v=>activeSet.add(v))}else{CONS.forEach(v=>activeSet.add((12-v)%12))}if(mode==='swap'){CONS.forEach(v=>{const sv=(12-v)%12;const p1=posOf(v),p2=posOf(sv);X.beginPath();X.moveTo(p1.x,p1.y);X.lineTo(p2.x,p2.y);const survives=CONS.has(sv);X.strokeStyle=survives?'rgba(81,207,102,0.3)':'rgba(255,107,107,0.4)';X.lineWidth=survives?1:2;X.setLineDash(survives?[]:[6,4]);X.stroke();X.setLineDash([])})}for(let i=0;i<12;i++){const p=posOf(i);const inActive=activeSet.has(i);const origCons=CONS.has(i);const rr=inActive?20:12;X.beginPath();X.arc(p.x,p.y,rr,0,2*Math.PI);if(mode==='orig'){X.fillStyle=origCons?'#1a3a2a':'#1a1a2a';X.strokeStyle=origCons?'#51cf66':'#333';X.lineWidth=origCons?2.5:1}else{const swapSrc=[...CONS].find(v=>(12-v)%12===i);const isMapped=swapSrc!==undefined;const survives=isMapped&&CONS.has(i);if(survives){X.fillStyle='#1a3a2a';X.strokeStyle='#51cf66';X.lineWidth=2.5}else if(isMapped&&!CONS.has(i)){X.fillStyle='#3a1a1a';X.strokeStyle='#ff6b6b';X.lineWidth=2.5}else if(origCons&&!isMapped){X.fillStyle='#2a2a1a';X.strokeStyle='#ffd43b88';X.lineWidth=1.5}else{X.fillStyle='#1a1a2a';X.strokeStyle='#333';X.lineWidth=1}}X.fill();X.stroke();X.fillStyle=inActive?'#fff':'#666';X.font=inActive?'bold 11px sans-serif':'10px sans-serif';X.textAlign='center';X.textBaseline='middle';X.fillText(NAMES[i],p.x,p.y-3);X.font='9px sans-serif';X.fillStyle=inActive?'#aaa':'#555';X.fillText(i+'',p.x,p.y+9)}X.fillStyle='#556';X.font='11px sans-serif';X.textAlign='center';const label=mode==='orig'?'Consonant intervals: {0, 3, 4, 7, 8, 9}':'After swap: {0, 3, 4, 5, 8, 9} — note 5 replaces 7!';X.fillText(label,CX,H-12)}const tbody=document.getElementById('tbody');tbody.innerHTML='';[0,3,4,7,8,9].forEach(v=>{const sv=(12-v)%12;const survives=CONS.has(sv);const tr=document.createElement('tr');tr.innerHTML=`<td>${FULL_NAMES[v]||v} (${v})</td><td>${NAMES[sv]} (${sv})</td><td class='${survives?'ok':'bad'}'>${survives?'✓ Consonant':'✗ Dissonant!'}</td>`;tbody.appendChild(tr)});draw()</script></body></html>"
