      "html": "<!DOCTYPE html><html><head><meta charset='utf-8'><title>Self-Loop Bottleneck</title><style>*{margin:0;padding:0;box-sizing:border-box}body{font-family:'Segoe UI',system-ui,sans-serif;background:#0d1117;color:#e6edf3;display:flex;flex-direction:column;align-items:center;padding:30px}h1{font-size:1.4em;font-weight:300;margin-bottom:5px}p.sub{color:#8b949e;font-size:.85em;margin-bottom:25px}.container{display:flex;gap:40px;flex-wrap:wrap;justify-content:center}.card{background:#161b22;border-radius:16px;padding:30px;width:300px;text-align:center;border:1px solid #30363d}.card h2{font-size:1.1em;margin-bottom:4px}.card .type{font-size:.8em;color:#8b949e;margin-bottom:20px}.loops-viz{display:flex;flex-wrap:wrap;gap:6px;justify-content:center;margin:15px 0;min-height:60px}.loop{width:28px;height:28px;border-radius:50%;display:flex;align-items:center;justify-content:center;font-size:.65em;font-weight:bold;animation:pop .4s ease-out backwards}.perfect .loop{background:linear-gradient(135deg,#ff6b6b,#c0392b);color:#fff}.imperfect .loop{background:linear-gradient(135deg,#4ecdc4,#1abc9c);color:#fff}@keyframes pop{from{transform:scale(0);opacity:0}to{transform:scale(1);opacity:1}}.count{font-size:2.5em;font-weight:bold;margin:10px 0}.ratio-bar{margin-top:30px;background:#161b22;border-radius:12px;padding:20px 30px;border:1px solid #30363d;max-width:640px;width:100%}.bar-container{display:flex;align-items:center;gap:10px;margin:8px 0}.bar{height:24px;border-radius:6px;transition:width 1s ease}.bar.perf{background:linear-gradient(90deg,#ff6b6b,#c0392b)}.bar.imp{background:linear-gradient(90deg,#4ecdc4,#1abc9c)}.bar-label{font-size:.85em;min-width:120px}.bar-val{font-size:.85em;font-weight:bold;min-width:40px;text-align:right}</style></head><body><h1>The Self-Loop Bottleneck</h1><p class='sub'>Perfect consonances are frozen in place — imperfect ones roam free</p><div class='container'><div class='card perfect'><h2>Perfect Fifth</h2><div class='type'>PERFECT CONSONANCE (7 semitones)</div><div class='loops-viz' id='perf-loops'></div><div class='count'>1</div><div>self-loop<br><small style='color:#8b949e'>Only the identity (0,0)</small></div></div><div class='card imperfect'><h2>Major Third</h2><div class='type'>IMPERFECT CONSONANCE (4 semitones)</div><div class='loops-viz' id='imp-loops'></div><div class='count'>12</div><div>self-loops<br><small style='color:#8b949e'>All parallel motions allowed</small></div></div></div><div class='ratio-bar'><h3 style='margin-bottom:12px;font-weight:400'>Incoming Voice Leadings (from all sources)</h3><div class='bar-container'><div class='bar-label'>Perfect cons.</div><div class='bar perf' style='width:254px'></div><div class='bar-val'>61</div></div><div class='bar-container'><div class='bar-label'>Imperfect cons.</div><div class='bar imp' style='width:300px'></div><div class='bar-val'>72</div></div><p style='margin-top:12px;font-size:.8em;color:#8b949e'>Perfect consonances suffer a 15% reduction in reachability — the mathematical cost of the parallel-fifths rule.</p></div><script>const pDiv=document.getElementById('perf-loops'),iDiv=document.getElementById('imp-loops');for(let k=0;k<1;k++){const d=document.createElement('div');d.className='loop';d.textContent='id';d.style.animationDelay=k*0.08+'s';pDiv.appendChild(d)}for(let k=0;k<12;k++){const d=document.createElement('div');d.className='loop';d.textContent=k;d.style.animationDelay=k*0.06+'s';iDiv.appendChild(d)}</script></body></html>"
