(100,220,180,0.3)';ctx.lineWidth=isBroken?2.5:1.5;const cpx=CX+(sa.x+sb.x-2*CX)*0.3,cpy=CY+(sa.y+sb.y-2*CY)*0.3;ctx.moveTo(sa.x,sa.y);ctx.quadraticCurveTo(cpx,cpy,sb.x,sb.y);ctx.stroke();ctx.setLineDash([]);const mx=(sa.x+sb.x)/2+(cpx-CX)*0.15,my=(sa.y+sb.y)/2+(cpy-CY)*0.15;ctx.fillStyle=isBroken?'#ff6b6b':'#4ecdc4';ctx.font='bold 10px sans-serif';ctx.textAlign='center';ctx.fillText(isBroken?'✗ BREAKS':'✓',mx,my)});all.forEach((v,i)=>{const isCons=consonant.has(i);const r=isCons?20:12;ctx.beginPath();ctx.arc(v.x,v.y,r,0,Math.PI*2);if(isCons){const neg=(12-i)%12;const negCons=consonant.has(neg);if(!negCons&&consonant.has(i)){ctx.fillStyle='#c0392b'}else{ctx.fillStyle='#1a6b5a'}}else{ctx.fillStyle=i===5?'#4a1a1a':'#1e2433'}ctx.fill();ctx.strokeStyle=isCons?'rgba(255,255,255,0.6)':'rgba(255,255,255,0.15)';ctx.lineWidth=isCons?2:1;ctx.stroke();ctx.fillStyle=isCons?'#fff':'rgba(255,255,255,0.35)';ctx.font=(isCons?'bold ':'')+' 11px sans-serif';ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillText(names[i],v.x,v.y);if(isCons||i===5){ctx.fillStyle=isCons?'rgba(255,255,255,0.5)':'rgba(255,100,100,0.7)';ctx.font='9px sans-serif';ctx.fillText(i+'st',v.x,v.y+r+12);if(i===5){ctx.fillStyle='#ff6b6b';ctx.font='bold 9px sans-serif';ctx.fillText('DISSONANT',v.x,v.y+r+24)}}});ctx.fillStyle='rgba(255,255,255,0.4)';ctx.font='11px sans-serif';ctx.textAlign='center';ctx.fillText('The chromatic circle (ZMod 12) — consonant intervals highlighted',CX,H-12);ctx.fillText('Arrows show the negation map i → −i',CX,H-28)}draw()</script></body></html>"
