→ Perfect 4th (5)</em> — consonant maps to dissonant!</div><script>const names=['P1/P8','m2','M2','m3','M3','P4','TT','P5','m6','M6','m7','M7'];const consonant=new Set([0,3,4,7,8,9]);const perfect=new Set([0,7]);const clock=document.getElementById('clock'),info=document.getElementById('info');const R=160,cx=200,cy=200;const nodes=[];for(let i=0;i<12;i++){const a=-Math.PI/2+i*2*Math.PI/12;const x=cx+R*Math.cos(a)-24,y=cy+R*Math.sin(a)-24;const div=document.createElement('div');div.className='note '+(perfect.has(i)?'perfect':consonant.has(i)?'consonant':'dissonant');div.textContent=names[i];div.style.left=x+'px';div.style.top=y+'px';div.dataset.interval=i;div.addEventListener('click',()=>showSwap(i));clock.appendChild(div);nodes.push(div)}let swapped=false;document.getElementById('swapBtn').addEventListener('click',()=>{swapped=!swapped;if(swapped){nodes.forEach((n,i)=>{const j=(12-i)%12;const a=-Math.PI/2+j*2*Math.PI/12;n.style.left=(cx+R*Math.cos(a)-24)+'px';n.style.top=(cy+R*Math.sin(a)-24)+'px';n.classList.remove('broken');if(consonant.has(i)&&!consonant.has(j)){n.classList.add('broken')}});info.innerHTML='<b>After voice swap:</b> Each interval i moved to position −i.<br>The <span style=\"color:#f85149;font-weight:700\">Perfect 5th</span> now sits at position 5 (Perfect 4th) — <span style=\"color:#f85149\">DISSONANT</span>!<br>Consonance is <b>not preserved</b> under voice exchange.'}else{nodes.forEach((n,i)=>{const a=-Math.PI/2+i*2*Math.PI/12;n.style.left=(cx+R*Math.cos(a)-24)+'px';n.style.top=(cy+R*Math.sin(a)-24)+'px';n.classList.remove('broken')});info.innerHTML='Voice swap reset. Click an interval or press Swap again.'}});function showSwap(i){const j=(12-i)%12;const iCons=consonant.has(i),jCons=consonant.has(j);nodes.forEach(n=>n.classList.remove('highlight','broken'));nodes[i].classList.add('highlight');nodes[j].classList.add('highlight');if(iCons&&!jCons)nodes[j].classList.add('broken');const status=iCons===jCons?'<span style=\"color:#3fb950\">✓ Preserved</