x(1,selfCount/3);X.stroke();X.fillStyle='#0a0a1a';X.fill();X.fillStyle='#aaa';X.font='9px sans-serif';X.textAlign='center';X.textBaseline='middle';X.fillText(selfCount,n.x+(n.r+12)*Math.cos(sa),n.y+(n.r+12)*Math.sin(sa))}const glow=selected&&selected.v===n.v;X.beginPath();X.arc(n.x,n.y,n.r,0,2*Math.PI);const col=PERF.has(n.v)?'#ff6b6b':'#51cf66';X.fillStyle=glow?col:(selected?'#222':'#1a1a2e');X.fill();X.strokeStyle=col;X.lineWidth=glow?3:1.5;X.stroke();X.fillStyle=glow?'#000':'#ddd';X.font='bold 13px sans-serif';X.textAlign='center';X.textBaseline='middle';X.fillText(NAMES[n.v],n.x,n.y-6);X.font='11px sans-serif';X.fillStyle=glow?'#333':'#999';X.fillText(`(${n.v})`,n.x,n.y+10)});if(selected){X.fillStyle='#556';X.font='11px sans-serif';X.textAlign='center';X.fillText('Click background to deselect',CX,H-16)}}C.addEventListener('click',e=>{const rect=C.getBoundingClientRect();const mx=(e.clientX-rect.left)*(W/rect.width);const my=(e.clientY-rect.top)*(H/rect.height);const hit=nodeAt(mx,my);selected=hit;draw();const det=document.getElementById('details');if(!hit){det.innerHTML='<p style=\"margin-top:12px;color:#667\">Nodes = consonant intervals mod 12.<br>Edge width ∝ number of permitted voice leadings.<br><br>Perfect consonances (red) have restricted incoming edges due to the parallel-motion prohibition.</p>';return}const v=hit.v;const isPerfect=PERF.has(v);const badge=isPerfect?'<span class=\"badge badge-p\">PERFECT</span>':'<span class=\"badge badge-i\">IMPERFECT</span>';let h=`<h3 style='margin-top:8px'>${NAMES[v]} ${badge}</h3>`;h+=`<p style='margin-top:8px'><strong>Self-loops:</strong> ${homCount(v,v)}</p>`;const inc=CONS.reduce((a,s)=>a+homCount(s,v),0);const out=CONS.reduce((a,t)=>a+homCount(v,t),0);h+=`<p><strong>Total incoming:</strong> ${inc}</p>`;h+=`<p><strong>Total outgoing:</strong> ${out}</p>`;h+='<table style=\"margin-top:10px;width:100%;font-size:.8rem\"><tr><th style=\"text-align:left\">From</th><th>Count</th></tr>';CONS.forEach(s=>{const c=homCount(